CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY roles_admin_write ON public.user_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.admin_profiles TO authenticated; GRANT ALL ON public.admin_profiles TO service_role;
ALTER TABLE public.admin_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_profiles_read ON public.admin_profiles FOR SELECT TO authenticated USING (auth_user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_profiles_write ON public.admin_profiles FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text NOT NULL UNIQUE, description text NOT NULL, duration text NOT NULL, start_date date, learning_mode text NOT NULL DEFAULT 'Online Classes', schedule text NOT NULL DEFAULT 'Monday – Friday', weekly_hours text NOT NULL DEFAULT '15–20 Hours per Week', tuition_kes integer NOT NULL CHECK (tuition_kes >= 0), tuition_usd integer NOT NULL CHECK (tuition_usd >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.courses TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY courses_public_read ON public.courses FOR SELECT TO anon, authenticated USING (is_active = true);
CREATE POLICY courses_admin_read ON public.courses FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY courses_admin_write ON public.courses FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER courses_updated BEFORE UPDATE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference_number text NOT NULL UNIQUE DEFAULT ('MTH-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), full_name text NOT NULL CHECK (length(full_name) BETWEEN 2 AND 100), email text NOT NULL CHECK (length(email) <= 255), contact_number text NOT NULL CHECK (length(contact_number) BETWEEN 7 AND 25), current_location text NOT NULL CHECK (length(current_location) BETWEEN 2 AND 120), course_id uuid NOT NULL REFERENCES public.courses(id), status text NOT NULL DEFAULT 'New' CHECK (status IN ('New','Under Review','Accepted','Rejected')), admin_notes text NOT NULL DEFAULT '', consent_given boolean NOT NULL CHECK (consent_given = true), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE, DELETE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_admin ON public.applications FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX applications_course_date ON public.applications(course_id,created_at DESC);
CREATE TRIGGER applications_updated BEFORE UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text CHECK (length(full_name) <= 100), email text CHECK (length(email) <= 255), category text NOT NULL CHECK (category IN ('General Feedback','Course Content','Learning Experience','Website Experience','Suggestions','Other')), message text NOT NULL CHECK (length(message) BETWEEN 5 AND 3000), status text NOT NULL DEFAULT 'Unread' CHECK (status IN ('Unread','Read','Reviewed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE, DELETE ON public.feedback TO authenticated; GRANT ALL ON public.feedback TO service_role;
ALTER TABLE public.feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY feedback_admin ON public.feedback FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER feedback_updated BEFORE UPDATE ON public.feedback FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.contact_inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK (length(full_name) BETWEEN 2 AND 100), email text NOT NULL CHECK (length(email) <= 255), subject text NOT NULL CHECK (length(subject) BETWEEN 2 AND 160), message text NOT NULL CHECK (length(message) BETWEEN 5 AND 3000), status text NOT NULL DEFAULT 'New' CHECK (status IN ('New','Read','Resolved')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE, DELETE ON public.contact_inquiries TO authenticated; GRANT ALL ON public.contact_inquiries TO service_role;
ALTER TABLE public.contact_inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY inquiries_admin ON public.contact_inquiries FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TRIGGER inquiries_updated BEFORE UPDATE ON public.contact_inquiries FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
